.ktb[data-appearance="classic"] [data-status="progress"] { color: #f59713; }
.ktb[data-appearance="classic"] [data-status="done"] { color: #377cff; }
.ktb-properties { margin-top: 10px; display: flex; flex-wrap: wrap; gap: 5px; }
.ktb-properties > span { max-width: 100%; display: inline-flex; align-items: center; gap: 5px; min-height: 22px; padding: 0 7px; border-radius: 7px; box-shadow: inset 0 0 0 1px var(--tb-line); font-size: 11.5px; line-height: 17px; color: var(--tb-text); }
.ktb-properties svg { width: 11px; height: 11px; }
.ktb-properties .ktb-priority { scale: .75; filter: grayscale(1); }
.ktb-properties .ktb-stat[data-soon="true"] { background: none; color: var(--tb-alert); }
.ktb-created { margin-top: 8px; font-size: 11.5px; line-height: 19px; color: var(--tb-muted); }
.ktb[data-compact="true"] :is(.ktb-properties,.ktb-created) { display: none; }
.ktb[data-appearance="classic"] .ktb-panel { padding: 14px 16px; border-radius: 16px; }
.ktb[data-appearance="classic"] :is(.ktb-panel-head,.ktb-panel-body) { padding-inline: 0; }
.ktb[data-appearance="classic"] .ktb-title-input { margin: 10px 0 24px; font-size: 17px; line-height: 22px; letter-spacing: -.02em; }
.ktb[data-appearance="classic"] .ktb-details-heading { display: none; }
.ktb[data-appearance="classic"] .ktb-field { display: block; margin-bottom: 14px; }
.ktb[data-appearance="classic"] .ktb-field > span { display: block; font-size: 12px; }
.ktb[data-appearance="classic"] .ktb-choices { gap: 6px; }
.ktb[data-appearance="classic"] .ktb-choice { padding: 3px 8px; min-height: 26px; box-shadow: inset 0 0 0 1px var(--tb-line); border-radius: 7px; }
.ktb[data-appearance="classic"] .ktb-choice:is([aria-pressed="true"],[data-checked]) { background: color-mix(in srgb, var(--tb-focus) 8%, var(--tb-card)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tb-focus) 37%, var(--tb-card)); }
@container (max-width: 380px) { .ktb[data-appearance="classic"] .ktb-search { flex: 1; } }
.ktb-avatar img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; }

.ktb[data-appearance="clean"] .ktb-column { animation: ktb-appear 420ms cubic-bezier(.22,1,.36,1) both; }
.ktb[data-appearance="classic"] .ktb-card { animation: ktb-classic-appear 320ms cubic-bezier(.22,1,.36,1) both; }
@keyframes ktb-classic-appear { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
.ktb svg[data-status="done"] rect { fill: currentColor; }
.ktb svg[data-status="done"] path { stroke: var(--tb-card); }
